    w = len(grid[0]) if h else 0

    pts = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                pts.append((r, c, grid[r][c]))

    if not pts:
        return [row[:] for row in grid]

    out = [[0 for _ in range(w)] for _ in range(h)]

    # Place 3x3 patterns around each point:
    # center keeps its own color, surrounding 8 cells use the paired opposite color.
    # In these tasks, each color appears twice diagonally.
    color_positions = {}
    for r, c, v in pts:
        color_positions.setdefault(v, []).append((r, c))

    colors = list(color_positions.keys())
    if len(colors) != 2:
        # Fallback: just return original if the structure is unexpected.
        return [row[:] for row in grid]

    a, b = colors[0], colors[1]

    for r, c, v in pts:
        surround = b if v == a else a
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = surround
        out[r][c] = v

    # Determine rectangle corners from the four points.
    rows = sorted(set(r for r, c, v in pts))
    cols = sorted(set(c for r, c, v in pts))
    if len(rows) != 2 or len(cols) != 2:
        return out

    r_top, r_bot = rows
    c_left, c_right = cols

    # Horizontal dotted connectors (color 5) on top and bottom center rows.
    for r in (r_top, r_bot):
        for x in range(c_left + 2, c_right - 1, 2):
            if 0 <= r < h and 0 <= x < w:
                out[r][x] = 5
        for x in range(c_right - 2, c_left + 1, -2):
            if 0 <= r < h and 0 <= x < w:
                out[r][x] = 5

    # Vertical dotted connectors (color 5) on left and right center columns.
    for c in (c_left, c_right):
        for y in range(r_top + 2, r_bot - 1, 2):
            if 0 <= y < h and 0 <= c < w:
                out[y][c] = 5
        for y in range(r_bot - 2, r_top + 1, -2):
            if 0 <= y < h and 0 <= c < w:
                out[y][c] = 5

    return out

